// Task 3c.29: technical_sheet_files (migration 032) and the private load SQL
// generated by scripts/catalog/technical-sheet-files.mjs, here from SYNTHETIC
// PDFs: the load is idempotent, the table refuses bytes that do not match
// their digest, size or PDF signature, and the rollback removes exactly the
// loaded sheets.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import pg from 'pg';
import { afterAll, beforeAll, describe, expect, test } from 'vitest';
import {
  planTechnicalSheetFiles, buildTechnicalSheetFilesSql, buildTechnicalSheetFilesRollbackSql,
} from '../../scripts/catalog/technical-sheet-files.mjs';

const enabled = process.env.TEST_PG_INTEGRATION === '1';
const describeIntegration = enabled ? describe : describe.skip;
const connection = {
  host: process.env.TEST_PGHOST || '127.0.0.1',
  port: Number(process.env.TEST_PGPORT || 55433),
  database: process.env.TEST_PGDATABASE || 'testdb',
  user: process.env.TEST_PGUSER || 'test',
  password: process.env.TEST_PGPASSWORD || 'test',
};
const fakePdf = (label) => Buffer.from(`%PDF-1.4\n% synthetic ${label}\n%%EOF\n`);

describeIntegration('technical_sheet_files load (synthetic PDFs)', () => {
  const client = new pg.Client(connection);
  let baseDir;
  const map = () => ({
    files: [
      { sku: 'demo-sheet-a', variant: null, file: 'ficha-demo-sheet-a.pdf', covers_variants: ['A1', 'A2'] },
      { sku: 'demo-sheet-a', variant: 'A2', file: 'ficha-demo-sheet-a-a2.pdf', covers_variants: ['A2'] },
      { sku: 'demo-sheet-b', variant: null, file: 'ficha-demo-sheet-a.pdf', covers_variants: [] },
    ],
  });
  const plan = (files = map()) => planTechnicalSheetFiles({ map: files, baseDir });
  const rows = async () => (await client.query(`
    SELECT sku, sheet_key, variant, covers_variants, file_name, sha256, size_bytes, active,
           encode(content, 'base64') AS content_base64, updated_at
    FROM technical_sheet_files WHERE sku LIKE 'demo-sheet-%' ORDER BY sku, sheet_key
  `)).rows;

  beforeAll(async () => {
    baseDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sheet-files-pg-'));
    fs.writeFileSync(path.join(baseDir, 'ficha-demo-sheet-a.pdf'), fakePdf('a'));
    fs.writeFileSync(path.join(baseDir, 'ficha-demo-sheet-a-a2.pdf'), fakePdf('a2'));
    await client.connect();
    // The load retires every sheet missing from its map, so it runs inside a
    // transaction that is rolled back: other suites' sheets are never touched.
    await client.query('BEGIN');
    await client.query("DELETE FROM technical_sheet_files WHERE sku LIKE 'demo-sheet-%'");
  });

  afterAll(async () => {
    await client.query('ROLLBACK');
    await client.end();
    fs.rmSync(baseDir, { recursive: true, force: true });
  });

  test('loads every sheet with its exact bytes, and a second load changes nothing', async () => {
    await client.query(buildTechnicalSheetFilesSql(plan()));
    const first = await rows();
    expect(first.map((row) => [row.sku, row.sheet_key, row.variant, row.active])).toEqual([
      ['demo-sheet-a', 'demo-sheet-a', null, true],
      ['demo-sheet-a', 'demo-sheet-a-a2', 'A2', true],
      ['demo-sheet-b', 'demo-sheet-a', null, true],
    ]);
    expect(Buffer.from(first[0].content_base64, 'base64').equals(fakePdf('a'))).toBe(true);
    expect(first[0].covers_variants).toEqual(['A1', 'A2']);

    // Every statement of a repeated load matches nothing: no row is rewritten.
    const results = await client.query(buildTechnicalSheetFilesSql(plan()));
    expect(results.map((result) => result.rowCount)).toEqual([0, 0, 0, 0]);
    expect(await rows()).toEqual(first);
  });

  test('new bytes replace the row; a sheet dropped from the map is deactivated, not deleted', async () => {
    fs.writeFileSync(path.join(baseDir, 'ficha-demo-sheet-a-a2.pdf'), fakePdf('a2 v2'));
    const reduced = map();
    reduced.files = reduced.files.filter((entry) => entry.sku === 'demo-sheet-a');
    await client.query(buildTechnicalSheetFilesSql(plan(reduced)));
    const after = await rows();
    expect(Buffer.from(after[1].content_base64, 'base64').equals(fakePdf('a2 v2'))).toBe(true);
    expect(after.find((row) => row.sku === 'demo-sheet-b')).toMatchObject({ active: false });

    await client.query(buildTechnicalSheetFilesSql(plan()));
    expect((await rows()).every((row) => row.active)).toBe(true);
  });

  test.each([
    ['a digest that does not match the bytes', "decode('JVBERi0xLjQK', 'base64'), repeat('0', 64), 9"],
    ['a size that does not match the bytes', "decode('JVBERi0xLjQK', 'base64'), encode(sha256(decode('JVBERi0xLjQK', 'base64')), 'hex'), 8"],
    ['bytes that are not a PDF', "convert_to('not a pdf', 'UTF8'), encode(sha256(convert_to('not a pdf', 'UTF8')), 'hex'), 9"],
  ])('the table refuses %s', async (_label, values) => {
    await client.query('SAVEPOINT refused_insert');
    await expect(client.query(`
      INSERT INTO technical_sheet_files (sku, sheet_key, file_name, content, sha256, size_bytes)
      VALUES ('demo-sheet-x', 'demo-sheet-x', 'ficha-demo-sheet-x.pdf', ${values})
    `)).rejects.toThrow(/check constraint/);
    await client.query('ROLLBACK TO SAVEPOINT refused_insert');
  });

  test('the rollback deletes exactly the loaded sheets', async () => {
    await client.query("INSERT INTO technical_sheet_files (sku, sheet_key, file_name, content, sha256, size_bytes) SELECT 'demo-sheet-keep', 'demo-sheet-keep', 'ficha-demo-sheet-keep.pdf', c, encode(sha256(c), 'hex'), octet_length(c) FROM (SELECT decode('JVBERi0xLjQK', 'base64') AS c) s");
    await client.query(buildTechnicalSheetFilesRollbackSql(plan()));
    expect((await rows()).map((row) => row.sku)).toEqual(['demo-sheet-keep']);
  });
});
